export default function App(){const[splash,setSplash]=useState(()=>!sessionStorage.getItem('cp-seen'));const[user,setUser]=useState<User|null>(null);const[authReady,setAuthReady]=useState(false);const[note,setNote]=useState<Note|null>(null);useEffect(()=>{if(!splash)return;const timer=setTimeout(()=>{setSplash(false);sessionStorage.setItem('cp-seen','1')},1500);return()=>clearTimeout(timer)},[splash]);useEffect(()=>{let cancelled=false;const restore=async()=>{const token=sessionStorage.getItem('cp-token');if(!token){if(!cancelled){setUser(null);setAuthReady(true)}}else{try{const studentProfile=await api<{firstname:string;lastname:string;email:string;walletNumber:string;schoolCode:string;matricNumber?:string}>('/Student/profile',{method:'GET'}).catch(()=>null);const merchantProfile=studentProfile?null:await api<{firstname:string;lastname:string;email:string;walletNumber:string;schoolCode:string;businessName?:string;shopLocation?:string;isApproved?:boolean}>('/Merchant/merchant/profile',{method:'GET'}).catch(()=>null);if(cancelled)return;const profile=studentProfile||merchantProfile;if(!profile){sessionStorage.removeItem('cp-token');sessionStorage.removeItem('cp-user');setUser(null);}else{const resolvedRole:Role=studentProfile?.matricNumber!==undefined?'Student':'Merchant';const nextUser={firstname:profile.firstname,lastname:profile.lastname,email:profile.email,walletNumber:profile.walletNumber,schoolCode:profile.schoolCode,role:resolvedRole};setUser(nextUser);sessionStorage.setItem('cp-user',JSON.stringify(nextUser));}}catch{if(!cancelled){sessionStorage.removeItem('cp-token');sessionStorage.removeItem('cp-user');setUser(null)}}finally{if(!cancelled){setAuthReady(true)}}}};void restore();return()=>{cancelled=true};},[]);const notify=(text:string,bad=false)=>{setNote({text,bad});setTimeout(()=>setNote(null),3500)};const save=(u:User|null)=>{setUser(u);if(u){sessionStorage.setItem('cp-user',JSON.stringify(u))}else{sessionStorage.removeItem('cp-user');sessionStorage.removeItem('cp-token')}};if(splash||!authReady)return <Splash/>;return <BrowserRouter>{note&&<div className={'toast '+(note.bad?'bad':'')}><BadgeCheck/>{note.text}</div>}<Routes><Route path="/" element={<Landing/>}/><Route path="/privacy" element={<Legal type="privacy"/>}/><Route path="/terms" element={<Legal type="terms"/>}/><Route path="/cookies" element={<Legal type="cookies"/>}/><Route path="/login" element={<Login save={save} notify={notify}/>}/><Route path="/staff-login" element={<StaffLogin save={save} notify={notify}/>}/><Route path="/register/:kind" element={<Register notify={notify}/>}/><Route path="/forgot" element={<Forgot notify={notify}/>}/><Route path="/app/*" element={user?<Shell user={user} save={save} notify={notify}/>:<Navigate to="/login"/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></BrowserRouter>}
function BrandIcon(){return <svg viewBox="0 0 48 48" aria-hidden="true"><path d="M8 14.5A6.5 6.5 0 0 1 14.5 8H34a6 6 0 0 1 6 6v4H17a5 5 0 0 0 0 10h23v6a6 6 0 0 1-6 6H14a6 6 0 0 1-6-6Z" fill="currentColor" opacity=".3"/><path d="M8 15h28a6 6 0 0 1 6 6v9a6 6 0 0 1-6 6H8V15Z" fill="currentColor"/><path d="M27 23v-2a5 5 0 0 1 10 0v2m-10 0h10v9H27z" fill="#143b35"/><circle cx="32" cy="27" r="1.5" fill="#dfffbb"/></svg>}
function Logo(){return <><div className="logo"><i><BrandIcon/></i>CampusPay</div>{location.pathname==='/'&&<CampusPortal/>}</>}
function CampusPortal(){const[target,setTarget]=useState<HTMLElement|null>(null);useEffect(()=>{const landing=document.querySelector('.landing');if(!landing)return;let host=document.getElementById('campus-security-root');if(!host){host=document.createElement('div');host.id='campus-security-root';const footer=landing.querySelector('.landing-footer');landing.insertBefore(host,footer)}if(host.dataset.claimed)return;host.dataset.claimed='true';setTarget(host);return()=>{delete host.dataset.claimed}},[]);return target?createPortal(<CampusInfo n={path=>location.assign(path)}/>,target):null}
function CampusInfo({n}:{n:(path:string)=>void}){const[open,setOpen]=useState(0);const faqs=[['How does CampusPay work for a university?','CampusPay gives each verified student and approved merchant a secure account connected to their school. Administrators can manage access, approve merchants, and oversee platform activity from one role-based workspace.'],['How are students and merchants verified?','Students register with their school code and matriculation details. Merchant accounts are reviewed and approved by an authorized school administrator before they can accept payments.'],['Is CampusPay secure?','Yes. Secure sessions, transaction PINs, account controls, role-based permissions, and monitored payment activity protect every interaction on the platform.'],['Can schools manage multiple campuses?','The administration tools are structured around school codes and permissions, making it possible to organize users and merchants across approved campus communities.'],['What support is available during onboarding?','Our team supports school setup, administrator access, merchant onboarding, and launch communication so each campus can adopt the platform confidently.']];return <><section className="campus-info" id="campuses"><div className="campus-info-head"><span>BUILT FOR UNIVERSITIES</span><h2>A better payment experience<br/>for the whole campus.</h2><p>Bring students, businesses, and administrators together with secure infrastructure designed specifically for university communities.</p></div><div className="campus-info-grid"><article><i><GraduationCap/></i><div><small>FOR STUDENTS</small><h3>Simple from day one</h3><p>Register with school details, fund an account, and pay across campus without relying on cash.</p></div></article><article><i><Store/></i><div><small>FOR MERCHANTS</small><h3>Built for campus business</h3><p>Accept verified payments, review transaction records, and withdraw earnings directly to a bank account.</p></div></article><article><i><ShieldCheck/></i><div><small>FOR ADMINISTRATORS</small><h3>Clarity and control</h3><p>Approve merchants, manage school access, and keep every role organized from one dashboard.</p></div></article></div><div className="campus-proof"><div><b>14</b><span>Partner institutions</span></div><div><b>12,000+</b><span>Active students</span></div><div><b>1,200+</b><span>Campus businesses</span></div><div><b>99.9%</b><span>Platform availability</span></div></div></section><section className="faq-section" id="security"><div className="faq-intro"><span>FREQUENTLY ASKED QUESTIONS</span><h2>Everything you need<br/>to know.</h2><p>Clear answers for students, campus businesses, and university teams considering CampusPay.</p><div className="faq-support"><i><HelpCircle/></i><div><b>Still have a question?</b><small>Our campus support team is ready to help.</small></div><a href="mailto:support@campuspay.ng">Contact support <ArrowRight/></a></div></div><div className="faq-list">{faqs.map(([question,answer],i)=><article className={open===i?'open':''} key={question}><button onClick={()=>setOpen(open===i?-1:i)} aria-expanded={open===i}><span>{String(i+1).padStart(2,'0')}</span><b>{question}</b><Plus/></button><div><p>{answer}</p></div></article>)}</div></section><section className="campus-callout"><div><span>READY FOR YOUR CAMPUS?</span><h2>Make payments simpler<br/>for everyone.</h2><p>Talk to our team about bringing CampusPay to your institution.</p></div><button onClick={()=>n('/staff-login')}>Explore administration <ArrowRight/></button></section></>}
